WITH flattened AS (SELECT id, coupon_codes, li_item.product_id, li_item.price, li_item.promo FROM carts LATERAL VIEW OUTER EXPLODE(items) x AS li_item), flattened_carts AS (SELECT product_id, price, promo, tag FROM flattened LATERAL VIEW EXPLODE(coupon_codes) li AS tag), metrics AS (SELECT *, CUME_DIST() OVER (PARTITION BY promo ORDER BY product_id DESC) AS product_id_cume_dist, RANK() OVER w_running AS price_rank FROM flattened_carts WINDOW w_running AS (PARTITION BY promo, tag ORDER BY price NULLS FIRST)), enriched AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY tag, promo ORDER BY price DESC NULLS LAST) AS price_percent_rank, ROUND(price_rank / SUM(price_rank) OVER (PARTITION BY promo), 4) AS price_rank_share FROM metrics), cleaned AS (SELECT *, price_rank_share + product_id_cume_dist AS price_rank_share_plus_product_id_cume_dist FROM enriched WHERE promo IS NOT NULL AND price_rank_share IS NOT NULL), base AS (SELECT product_id, price, promo, tag, price_percent_rank, price_rank_share, price_rank_share_plus_product_id_cume_dist, ROUND(product_id * 100, 2) AS adjusted_product_id, CEIL(price_rank) AS price_rank_whole, COALESCE(promo, 'NONE') AS promo_clean FROM cleaned WHERE promo IS NOT NULL AND price_rank IS NOT NULL), scored AS (SELECT *, AVG(price_rank_share) OVER w_recent AS tag_avg_price_rank_share, MIN(price) OVER w_recent AS tag_min_price, CUME_DIST() OVER w_part AS price_cume_dist, COUNT(price_percent_rank) OVER w_recent AS tag_count_price_percent_rank FROM base WINDOW w_recent AS (PARTITION BY tag), w_part AS (ORDER BY price DESC)) SELECT CASE WHEN price_percent_rank >= 0.74 THEN 'LARGE' ELSE 'SMALL' END AS price_percent_rank_tier, COUNT(*) AS event_count, APPROX_PERCENTILE(price_percent_rank, 0.5) AS price_percent_rank_p50, COUNT(DISTINCT promo) AS distinct_promos FROM scored GROUP BY CASE WHEN price_percent_rank >= 0.74 THEN 'LARGE' ELSE 'SMALL' END;
